import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.hasSize;

@Test
void pobranieZadaniaSprawdzaZagniezdzoneIListowePola() {
    given()
        .when()
            .get("/api/zadania/1")
        .then()
            .statusCode(200)
            .body("tytul", equalTo("Nauczyc sie REST Assured"))
            .body("autor.imie", equalTo("Jan"))
            .body("tagi", hasSize(3))
            .body("tagi[0]", equalTo("testy"));
}

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;

// REST Assured deserializuje WŁASNYM ObjectMapperem (nie tym ze Springa) - domyślnie
// NIEZNANE pola JSON (np. "autor", "tagi") powodują UnrecognizedPropertyException
@JsonIgnoreProperties(ignoreUnknown = true)
record ZadanieDto(Long id, String tytul, boolean wykonane) {}

@Test
void pobranieZadaniaZdeserializowaneDoDto() {
    ZadanieDto zadanie =
        given()
            .when()
                .get("/api/zadania/1")
            .then()
                .statusCode(200)
            .extract()
                .as(ZadanieDto.class);

    assertThat(zadanie.tytul()).isEqualTo("Nauczyc sie REST Assured");
    assertThat(zadanie.wykonane()).isFalse();
}

given()
    .when().get("/api/produkty/1")
    .then()
        .body("cena", equalTo(19.99));
// BLEDNIE: domyslnie JsonPath zwraca 19.99 jako Float:
//   JSON path cena doesn't match.
//   Expected: <19.99>
//     Actual: <19.99F>
// Uwaga: closeTo(19.99, 0.001) przy domyslnej konfiguracji zawiedzie TAK SAMO
// (closeTo akceptuje tylko Double)

import io.restassured.config.JsonConfig;
import io.restassured.path.json.config.JsonPathConfig.NumberReturnType;
import static org.hamcrest.Matchers.closeTo;
import static org.hamcrest.Matchers.equalTo;

// Wariant 1: liczby jako Double + porownanie z tolerancja
given()
    .config(RestAssured.config().jsonConfig(
        JsonConfig.jsonConfig().numberReturnType(NumberReturnType.DOUBLE)))
    .when().get("/api/produkty/1")
    .then()
        .body("cena", closeTo(19.99, 0.001));

// Wariant 2 (kwoty pieniezne): liczby jako BigDecimal + dokladne porownanie
given()
    .config(RestAssured.config().jsonConfig(
        JsonConfig.jsonConfig().numberReturnType(NumberReturnType.BIG_DECIMAL)))
    .when().get("/api/produkty/1")
    .then()
        .body("cena", equalTo(new BigDecimal("19.99")));

// Konfiguracje mozna tez ustawic raz dla wszystkich testow:
// RestAssured.config = RestAssured.config().jsonConfig(...);

